solution:
def classify(code):
    if 200 <= code < 300:
        return "ok"
    if 400 <= code < 500:
        return "client error"
    return "server error"

alt:
def classify(code):
    d = code // 100
    return {2: "ok", 4: "client error"}.get(d, "server error")
